/// <summary>
/// This runnable job is used to update the Order number with PurchId field of METDutyRollVariance table. Done as part of Task 262865 of CB251 Excise register.
/// </summary>
internal final class METUpdateOrdNumOfMETDutyRollVarianceRunnable
{
}

Method.Source:
/// <summary>
/// Class entry point.This runnable job is used to update the Order number with PurchId field of METDutyRollVariance table. Done as part of Task 262865 of CB251.
/// Plan to drop PurchId later and maintain Order number field as part of index later enabling to store both Purhase orders id's and Tansfer orders.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    CompanyInfo companyInfo;

    // Loop through all legal entities
    while select DataArea from companyInfo
    {
        changeCompany(companyInfo.DataArea)
        {
            int64 recordsToUpdate;
            METDutyRollVariance metDutyRollVarianceUpdate;

            // Count the records where PurchId is not empty and OrderNumber is different
            select count(RecId) from metDutyRollVarianceUpdate
                where metDutyRollVarianceUpdate.PurchId != '';

            recordsToUpdate = metDutyRollVarianceUpdate.RecId;

            if (recordsToUpdate > 0)
            {
                ttsBegin;

                while select forupdate metDutyRollVarianceUpdate
                    where metDutyRollVarianceUpdate.OrderNumber == ''
                {
                    metDutyRollVarianceUpdate.OrderNumber = metDutyRollVarianceUpdate.PurchId;

                    if (PurchTable::exist(metDutyRollVarianceUpdate.PurchId))
                    {
                        metDutyRollVarianceUpdate.InventTransType = InventTransType::Purch;
                    }
                    else if (InventTransferTable::exist(metDutyRollVarianceUpdate.PurchId))
                    {
                        InventTransferStatus inventTransferStatus =  InventTransferTable::find(metDutyRollVarianceUpdate.PurchId).TransferStatus;
                        if (inventTransferStatus == InventTransferStatus::Received)
                        {
                            metDutyRollVarianceUpdate.InventTransType = InventTransType::TransferOrderReceive;
                        }
                        else if (inventTransferStatus == InventTransferStatus::Shipped)
                        {    
                            metDutyRollVarianceUpdate.InventTransType = InventTransType::TransferOrderShip;
                        }
                    }

                    metDutyRollVarianceUpdate.doUpdate();
                }

                ttsCommit;

                info(strFmt("Updated %1 record(s) in METDutyRollVariance for company: %2",
                        recordsToUpdate, companyInfo.DataArea));
            }
            else
            {
                info(strFmt("No records to update in company: %1", companyInfo.DataArea));
            }
        }
    }

    info("Execution to update the Order number with PurchId field of METDutyRollVariance table is completed.");
}
